// ── Decode JWT (local — no network call) ─────────────────────────────────────
const body = $json.body || {};
const token = (body.token || '').trim();

const ROLE_LEVELS = {
  trainee: 1, engineer: 2, sme: 3,
  supervisor: 4, head: 5, admin: 6, superadmin: 7
};

if (!token) {
  return { authValid: false, reason: 'No token provided', body };
}

try {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('Bad token structure');

  const pad = s => s + '='.repeat((4 - s.length % 4) % 4);
  const decode = s => JSON.parse(Buffer.from(pad(s.replace(/-/g,'+').replace(/_/g,'/')), 'base64').toString('utf8'));

  const payload = decode(parts[1]);
  const now = Math.floor(Date.now() / 1000);
  if (payload.exp && payload.exp < now) {
    return { authValid: false, reason: 'Token expired', body };
  }

  const groups = (payload.groups || []).map(g => g.replace(/^\//, '').toLowerCase());
  let highestRole = 'trainee';
  let roleLevel = 1;
  for (const g of groups) {
    const lvl = ROLE_LEVELS[g];
    if (lvl && lvl > roleLevel) { roleLevel = lvl; highestRole = g; }
  }

  return {
    authValid: true,
    username: payload.preferred_username || payload.sub || 'unknown',
    name: payload.name || payload.preferred_username || '',
    email: payload.email || '',
    groups,
    roleLevel,
    highestRole,
    canModifyOthers: roleLevel >= 3,
    body
  };
} catch (err) {
  return { authValid: false, reason: 'Token decode error: ' + err.message, body };
}

