// Parse the OCR data
const ocrData = $input.first().json;
const markdown = ocrData.pages[0].markdown;

function parseRosterTable(markdown) {
  const lines = markdown.split('\n');
  let userNameIndex = -1;
  let dateIndices = [];
  let headerRowIndex = -1;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line.trim() || line.includes('---')) continue;

    if (line.includes('UserName') || line.includes('User Name')) {
      headerRowIndex = i;
      const headerRow = line.split('|').map(cell => cell.trim());
      for (let j = 0; j < headerRow.length; j++) {
        if (headerRow[j].includes('UserName') || headerRow[j].includes('User Name')) {
          userNameIndex = j; break;
        }
      }
      if (i > 0) {
        const prevLine = lines[i - 1];
        if (prevLine && !prevLine.includes('---')) {
          const prevRow = prevLine.split('|').map(cell => cell.trim());
          for (let j = 0; j < prevRow.length; j++) {
            if (prevRow[j].match(/^\d{2}-[A-Za-z]{3}$/) || prevRow[j].match(/^\d{1,2}\/\d{1,2}/)) {
              dateIndices.push({ index: j, date: prevRow[j] });
            }
          }
        }
      }
      if (dateIndices.length === 0) {
        if (i + 1 < lines.length) {
          const nextLine = lines[i + 1];
          if (nextLine && !nextLine.includes('---')) {
            const nextRow = nextLine.split('|').map(cell => cell.trim());
            for (let j = 0; j < nextRow.length; j++) {
              if (nextRow[j].match(/^\d{2}-[A-Za-z]{3}$/) || nextRow[j].match(/^\d{1,2}\/\d{1,2}/)) {
                dateIndices.push({ index: j, date: nextRow[j] });
              }
            }
          }
        }
      }
      break;
    }
  }

  if (userNameIndex === -1 || dateIndices.length === 0) {
    return { success: false, message: 'Could not find UserName or date columns in the roster table', data: [] };
  }

  const data = [];
  for (let i = headerRowIndex + 1; i < lines.length; i++) {
    const line = lines[i];
    if (!line.trim() || line.includes('---')) continue;
    const cells = line.split('|').map(cell => cell.trim());
    const engineerName = cells[userNameIndex];
    if (!engineerName || engineerName === '') continue;
    for (const { index, date } of dateIndices) {
      const shiftType = cells[index];
      if (shiftType && shiftType !== '') {
        const dateObj = new Date(date + '-2025');
        const formattedDate = !isNaN(dateObj) ? dateObj.toISOString().split('T')[0] : date;
        data.push({ engineer_name: engineerName, date: formattedDate, shift_type: shiftType });
      }
    }
  }
  return data.length > 0 ? { success: true, data, count: data.length, message: 'Roster parsed successfully' } : { success: false, message: 'No valid roster data found', data: [] };
}

const result = parseRosterTable(markdown);
return result;

const rawData = $node["Parse OCR Data"].json;
if (!rawData || !rawData.data || !Array.isArray(rawData.data)) return rawData;

const invalidNames = ['---', 'UserName', 'Aug - 25', '', 'Total', 'Sheet1', 'Sheet2'];
const invalidShiftTypes = ['01-Aug','02-Aug','03-Aug','04-Aug','05-Aug','06-Aug','07-Aug',
  '08-Aug','09-Aug','10-Aug','11-Aug','12-Aug','13-Aug','14-Aug','Sheet1','Sheet2','---'];

const cleanedData = rawData.data.filter(entry =>
  !invalidNames.includes(entry.engineer_name.trim()) &&
  !invalidShiftTypes.includes(entry.shift_type.trim())
);

return {
  success: rawData.success,
  data: cleanedData,
  count: cleanedData.length,
  originalCount: rawData.data.length,
  filtered: rawData.data.length - cleanedData.length,
  message: rawData.message
};

const rosterData = $node["Clean Roster Data"].json.data;
const uniqueEngineers = new Set();
for (const entry of rosterData) {
  const name = entry.engineer_name.trim();
  if (name && name.length > 1) uniqueEngineers.add(name);
}
const valueStrings = Array.from(uniqueEngineers).map(n => `('${n.replace(/'/g, "\\'")}')`);
return { query: `INSERT IGNORE INTO roster_automation_flow_engineers (name) VALUES ${valueStrings.join(',')}` };

const rosterData = $node["Clean Roster Data"].json.data;
const allInputs = $input.all();
let engineerIds = [];
if (allInputs.length > 0) {
  const first = allInputs[0].json;
  engineerIds = Array.isArray(first) ? first : allInputs.map(i => i.json);
}
const engineerNameToId = {};
for (const e of engineerIds) { if (e && e.name && e.id) engineerNameToId[e.name] = e.id; }

const queries = [];
for (const entry of rosterData) {
  const engineerId = engineerNameToId[entry.engineer_name];
  if (engineerId) {
    queries.push({
      engineer_id: engineerId,
      engineer_name: entry.engineer_name,
      date: entry.date,
      new_shift_type: entry.shift_type,
      query: `SELECT engineer_id, date, shift_type, last_updated FROM roster_automation_flow_roster WHERE engineer_id = ${engineerId} AND date = '${entry.date}'`
    });
  }
}
return queries;

const allItems = $input.all();
const queryInputs = $("Generate Conflict Check Queries").all();
const engineerIdsInputs = $("Get Engineer IDs").all();
let engineerIds = [];
if (engineerIdsInputs.length > 0) {
  const first = engineerIdsInputs[0].json;
  engineerIds = Array.isArray(first) ? first : engineerIdsInputs.map(i => i.json);
}
const engineerNameToId = {};
for (const e of engineerIds) engineerNameToId[e.name] = e.id;

const queryResultsMap = new Map();
for (const item of allItems) {
  if (item?.json?.engineer_id !== undefined && item?.json?.date !== undefined && item?.json?.shift_type !== undefined) {
    queryResultsMap.set(`${item.json.engineer_id}_${item.json.date}`, item.json);
  }
}

const conflicts = [], existingEntries = [], newEntries = [];
for (const qi of queryInputs) {
  const q = qi.json;
  const existing = queryResultsMap.get(`${q.engineer_id}_${q.date}`);
  if (!existing) {
    newEntries.push({ engineer_id: q.engineer_id, engineer_name: q.engineer_name, date: q.date, shift_type: q.new_shift_type });
  } else if (existing.shift_type === q.new_shift_type) {
    existingEntries.push({ engineer_id: existing.engineer_id, engineer_name: q.engineer_name, date: q.date, shift_type: q.new_shift_type });
  } else {
    conflicts.push({ engineer_id: existing.engineer_id, engineer_name: q.engineer_name, date: q.date, old_shift_type: existing.shift_type, new_shift_type: q.new_shift_type });
  }
}

return {
  conflicts, existingEntries, newEntries,
  hasConflicts: conflicts.length > 0,
  hasNewEntries: newEntries.length > 0,
  summary: { totalProcessed: queryInputs.length, conflicts: conflicts.length, existing: existingEntries.length, new: newEntries.length }
};

const analysisData = $node["Analyze Conflicts"].json;
const newEntries = analysisData.newEntries || [];
const username = $('Decode JWT').first().json.username;
const sqls = newEntries.map(e =>
  `INSERT INTO roster_automation_flow_roster (engineer_id, date, shift_type, last_updated) VALUES (${e.engineer_id}, '${e.date}', '${e.shift_type}', CURRENT_TIMESTAMP)`
);
return {
  analysisData, newEntrySqlStatements: sqls, newEntriesCount: newEntries.length,
  username, conflictsCount: analysisData.conflicts.length,
  conflicts: analysisData.conflicts, newEntries, existingEntries: analysisData.existingEntries,
  summary: analysisData.summary
};

const analysisData = $node["Analyze Conflicts"].json;
const newEntries = analysisData.newEntries || [];
const username = $('Decode JWT').first().json.username;
const sqls = newEntries.map(e =>
  `INSERT INTO roster_automation_flow_roster (engineer_id, date, shift_type, last_updated) VALUES (${e.engineer_id}, '${e.date}', '${e.shift_type}', CURRENT_TIMESTAMP)`
);
return {
  analysisData, newEntrySqlStatements: sqls, newEntriesCount: newEntries.length,
  username, conflictsCount: analysisData.conflicts.length,
  conflicts: analysisData.conflicts, newEntries, existingEntries: analysisData.existingEntries,
  summary: analysisData.summary
};

const analysisData = $node["Analyze Conflicts"].json;
const username = $('Decode JWT').first().json.username;
const sessionId = 'conflict_' + username + '_' + Date.now();
const conflictData = {
  conflicts: analysisData.conflicts,
  newEntries: analysisData.newEntries,
  existingEntries: analysisData.existingEntries,
  summary: analysisData.summary,
  username, sessionId,
  newEntriesAlreadyProcessed: (analysisData.newEntries || []).length
};
const expiresAt = new Date(Date.now() + 10 * 60 * 1000).toISOString().slice(0,19).replace('T',' ');
return { sessionId, username, conflictData: JSON.stringify(conflictData), expiresAt, originalData: analysisData };

const body = $('Roster Upload Webhook').first().json.body || {};
const decision = (body.decision || '').toLowerCase().trim();
const username = $('Decode JWT').first().json.username;
const queryResults = $('Retrieve Conflict Data Web').all();

if (!queryResults || queryResults.length === 0 || !queryResults[0].json) {
  return { action: 'no_data', message: '❌ Session expired. Please upload the roster image again.', username };
}

const rec = queryResults[0].json;
const storedData = typeof rec.conflict_data === 'string' ? JSON.parse(rec.conflict_data) : rec.conflict_data;
const sessionId = rec.session_id;
const isApproved = decision === 'yes' || decision === 'approve';
const isRejected = decision === 'no'  || decision === 'reject';

if (isApproved) {
  return { action: 'approved', message: '✅ Approved! Applying updates…', username, conflictData: storedData, sessionId };
} else if (isRejected) {
  return { action: 'rejected', message: '❌ Changes rejected.', username, sessionId };
} else {
  return { action: 'invalid', message: 'Invalid decision. Expected "yes" or "no".', username };
}

const inputData = $input.all()[0].json;
const conflictData = inputData.conflictData;
const conflicts = conflictData.conflicts || [];
const username = inputData.username || 'app_user';
const sessionId = inputData.sessionId;
const sqlOperations = [];

for (const c of conflicts) {
  sqlOperations.push(`UPDATE roster_automation_flow_roster SET shift_type = '${c.new_shift_type}', last_updated = CURRENT_TIMESTAMP WHERE engineer_id = ${c.engineer_id} AND date = '${c.date}'`);
  sqlOperations.push(`INSERT INTO roster_automation_flow_conflicts (engineer_id, date, old_shift_type, new_shift_type, resolved_by, resolved_at) VALUES (${c.engineer_id}, '${c.date}', '${c.old_shift_type}', '${c.new_shift_type}', '${username}', CURRENT_TIMESTAMP)`);
}

let message = '✅ Roster Updated Successfully!\n\n';
if (conflicts.length > 0) {
  message += `🔄 Conflicts Resolved: ${conflicts.length}\n`;
  conflicts.forEach(c => { message += `  • ${c.engineer_name}: ${c.old_shift_type} → ${c.new_shift_type} (${c.date})\n`; });
}

return { sqlOperations, message, conflictsResolved: conflicts.length, username, sessionId };

const data = $('Process New Entries Web').first().json;
const responseBody = JSON.stringify({
  status: 'success',
  message: '✅ Roster updated! ' + (data.newEntriesCount || 0) + ' new entries added. ' + (data.existingEntries || []).length + ' already existed.',
  newEntries: data.newEntriesCount || 0,
  existingUnchanged: (data.existingEntries || []).length
});
return { responseBody };

const sessionData = $('Store Conflict Data Web').first().json;
const analysisData  = $('Analyze Conflicts').first().json;
const newData       = $('Process New Entries With Conflicts').first().json;
const responseBody = JSON.stringify({
  status: 'conflict',
  sessionId: sessionData.sessionId,
  message: '⚠️ Found ' + (analysisData.conflicts || []).length + ' conflict(s) requiring approval.',
  conflicts: analysisData.conflicts || [],
  newEntriesInserted: newData.newEntriesCount || 0,
  existingUnchanged: (analysisData.existingEntries || []).length,
  summary: analysisData.summary || {}
});
return { responseBody };

const data = $('Apply Updates Web').first().json;
const responseBody = JSON.stringify({
  status: 'success',
  message: data.message || '✅ Roster updated.',
  conflictsResolved: data.conflictsResolved || 0
});
return { responseBody };
